package com.kartyavya.report.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; @Service public class LocationService{@Value("${municipality.min-latitude:18.0}")double minLat;@Value("${municipality.max-latitude:22.5}")double maxLat;@Value("${municipality.min-longitude:72.0}")double minLng;@Value("${municipality.max-longitude:80.5}")double maxLng;public void verify(double lat,double lng){if(lat<minLat||lat>maxLat||lng<minLng||lng>maxLng)throw new IllegalArgumentException("Selected location is outside the configured municipal service area");}public double distance(double a,double b,double c,double d){double r=6371,dl=Math.toRadians(c-a),dn=Math.toRadians(d-b),x=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(c))*Math.sin(dn/2)*Math.sin(dn/2);return 2*r*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}}
